import{_ as a,C as i,o as n,c as o,E as r,a2 as s}from"./chunks/framework.BOeh4kYD.js";const f=JSON.parse('{"title":"A Validated Ancestor Does Not Validate the Deployed Artifact","description":"","frontmatter":{"title":"A Validated Ancestor Does Not Validate the Deployed Artifact","date":"2026-09-16","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"部署流程对已验证模型执行可能改变行为的转换后，安全证据应归属于已验证祖先、转换配方，还是最终真正运行的精确制品？","summary":"Controlled adversarial evidence shows that a benign full-precision checkpoint can exhibit targeted behavior after selected quantization. Lineage proves origin, not current behavior; deployment admission must bind the exact transformed artifact and its validation.","sources":["research/analysis/Q-20260916-02-transformed-artifact-is-a-new-evidence-subject.md"],"item_id":"Q-20260916-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-16-validated-ancestor-not-deployed-artifact-cover-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-16-validated-ancestor-not-deployed-artifact.md","filePath":"en/industry/2026-09-16-validated-ancestor-not-deployed-artifact.md","lastUpdated":1789665186000}'),d={name:"en/industry/2026-09-16-validated-ancestor-not-deployed-artifact.md"};function l(c,e,h,u,p,m){const t=i("ArticleCover");return n(),o("div",null,[r(t,{image:"/assets/covers/daily-2026-09-16-validated-ancestor-not-deployed-artifact-cover-v2.webp",kicker:"Industry Architecture · Daily Research",title:"A Validated Ancestor Does Not Validate the Deployed Artifact",summary:"Controlled adversarial evidence shows that a benign full-precision checkpoint can exhibit targeted behavior after selected quantization. Lineage proves origin, not current behavior; deployment admission must bind the exact transformed artifact and its validation.",version:"Q-20260916-02",status:"Daily Runtime V5 · 2026-09-16",languageHref:"/zh/industry/2026-09-16-validated-ancestor-not-deployed-artifact",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-validated-ancestor-does-not-validate-the-deployed-artifact" tabindex="-1">A Validated Ancestor Does Not Validate the Deployed Artifact <a class="header-anchor" href="#a-validated-ancestor-does-not-validate-the-deployed-artifact" aria-label="Permalink to &quot;A Validated Ancestor Does Not Validate the Deployed Artifact&quot;">​</a></h1><p>A model checkpoint passes safety tests and is approved. Before deployment, the platform quantizes, converts, or compiles it to reduce cost. The system that reaches production is a new set of bytes, yet the admission record still points to the upstream model name. Lineage remains intact while the evidence subject may have changed.</p><p>The issue is not that every transformation is harmful. The issue is whether a transformation can alter behavior relevant to admission. When it can, the output becomes a new evidence subject. Knowing where it came from cannot substitute for testing what it does in its deployed form.</p><h2 id="before-and-after-can-be-different-behavioral-subjects" tabindex="-1">Before and After Can Be Different Behavioral Subjects <a class="header-anchor" href="#before-and-after-can-be-different-behavioral-subjects" aria-label="Permalink to &quot;Before and After Can Be Different Behavioral Subjects&quot;">​</a></h2><p>The same-date Research Object examines AgentQ and its quantization-triggered function-action backdoor experiments. In the paper&#39;s main constructed setting, every reported full-precision checkpoint has attack success rate zero for the tested backdoor behavior. After selected codebook quantization, the worst-codebook attack success rate exceeds 0.76 in every main-table model/task cell, and 12 of 18 cells exceed 0.90.</p><p>This is not a prevalence estimate for ordinary quantization. The researchers deliberately design structured perturbations that remain benign at full precision and produce trigger-action behavior after specific quantization and codebook transformations. The result establishes possibility and mechanism: two artifacts in the same lineage can have materially different observed behavior.</p><p>Ancestor safety evidence therefore cannot simply be copied to the descendant. Even perfect traceability of source, build, and parentage does not make the final executable the same behavioral evidence subject.</p><h2 id="lineage-answers-origin-validation-answers-behavior" tabindex="-1">Lineage Answers Origin; Validation Answers Behavior <a class="header-anchor" href="#lineage-answers-origin-validation-answers-behavior" aria-label="Permalink to &quot;Lineage Answers Origin; Validation Answers Behavior&quot;">​</a></h2><p>Cryptographic provenance can answer which checkpoint, inputs, and build chain produced an artifact. It is indispensable for supply-chain security, accountability, and reproducibility.</p><p>It does not answer what the resulting bytes did under the tested conditions. Post-transform validation asks whether behavior, safety, utility, and structured outputs still meet admission criteria. These evidence types complement one another but are not interchangeable.</p><p>Treating lineage as behavioral equivalence creates an inheritance error: the ancestor passed, therefore the descendant passes. The opposite shortcut is also weak. Testing only the output while losing ancestor and transform identity makes failures hard to reproduce, explain, or roll back.</p><h2 id="five-identities-belong-in-one-evidence-chain" tabindex="-1">Five Identities Belong in One Evidence Chain <a class="header-anchor" href="#five-identities-belong-in-one-evidence-chain" aria-label="Permalink to &quot;Five Identities Belong in One Evidence Chain&quot;">​</a></h2><p>A governed deployment contract should preserve at least five distinct identities.</p><ul><li><strong>Ancestor identity:</strong> exact checkpoint hash, origin, version, and pre-transform validation.</li><li><strong>Transform identity:</strong> transform type, tool and version, parameters, codebook, environment, and inputs.</li><li><strong>Output artifact identity:</strong> hash of the actual executable bytes, format, target runtime, and parent references.</li><li><strong>Post-transform validation identity:</strong> behavioral, safety, utility, and structural checks run against that exact output.</li><li><strong>Deployment admission identity:</strong> admitted output hash, policy version, target, scope, and invalidation conditions.</li></ul><p>A transform label such as “4-bit quantization” is not sufficient. It omits implementation, version, codebook, and parameters. A model alias is also insufficient because it may later resolve to different bytes. The deployment target should ultimately resolve to an immutable, admitted artifact hash.</p><h2 id="validation-must-face-the-bytes-that-will-run" tabindex="-1">Validation Must Face the Bytes That Will Run <a class="header-anchor" href="#validation-must-face-the-bytes-that-will-run" aria-label="Permalink to &quot;Validation Must Face the Bytes That Will Run&quot;">​</a></h2><p>Validation pipelines are often strongest before transformation. The upstream checkpoint receives extensive evaluation, then compression, compilation, and packaging happen closer to deployment with progressively lighter checks. If these steps can alter relevant behavior, the test order is reversed.</p><p>A stronger sequence first materializes the final artifact and then runs risk-appropriate tests against the exact output. The record should include artifact hash, validator and policy versions, test environment, results, limits, and unresolved findings. That evidence package—not the ancestor&#39;s reputation—supports admission.</p><p>When the bytes, behavior-relevant parameters, or target environment change, the prior admission should expire or enter an explicit equivalence decision. An unchanged human-readable name must not keep old evidence active.</p><h2 id="not-every-transform-needs-the-same-retest-depth" tabindex="-1">Not Every Transform Needs the Same Retest Depth <a class="header-anchor" href="#not-every-transform-needs-the-same-retest-depth" aria-label="Permalink to &quot;Not Every Transform Needs the Same Retest Depth&quot;">​</a></h2><p>The adversarial construction does not justify a universal rule that every quantization requires a complete evaluation campaign. The study covers bounded models, sizes, triggers, actions, and quantization settings. It does not show that routine NF4, FP4, or INT8 conversion spontaneously creates the same vulnerability.</p><p>Testing cost can be managed by risk tiers. Byte-preserving or formally equivalent transforms may use equivalence evidence accepted by versioned policy. Low-impact changes may use sampled regression. Transforms that affect tool calls, structured actions, or safety boundaries need deeper output-specific validation.</p><p>The crucial property is auditability: who proved equivalence, which admission criteria the proof covers, which policy version accepts it, and which changes invalidate it.</p><h2 id="a-minimal-control-from-validation-to-deployment" tabindex="-1">A Minimal Control from Validation to Deployment <a class="header-anchor" href="#a-minimal-control-from-validation-to-deployment" aria-label="Permalink to &quot;A Minimal Control from Validation to Deployment&quot;">​</a></h2><p>A practical chain can work as follows:</p><ol><li>Bind the ancestor hash and its existing evidence.</li><li>Record exact transform tool, version, parameters, and environment.</li><li>Materialize the output and calculate its immutable hash.</li><li>Run risk-tiered post-transform tests against that hash.</li><li>Preserve results, limits, and unresolved findings in a separate validation record.</li><li>Let admission reference only the exact output hash and policy version.</li><li>Attest at deployment that the executed bytes are the admitted bytes.</li><li>Treat later transforms or byte changes as invalidation, equivalence review, or retest triggers.</li></ol><p>Rollback becomes clearer as well. Evidence about a rejected descendant remains; the previously admitted ancestor state is not rewritten. The deployment target simply resolves back to an artifact whose admission remains valid.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>AgentQ is a deliberately constructed backdoor study, not a survey of normal quantization pipelines. Worst-codebook results are selected inside the study&#39;s threat model and cannot support a claim that every quantized artifact is dangerous. The strongest transferable evidence is that a transform can change the evidence subject—not that quantization is inherently unsafe.</p><p>Open questions include which transform properties automatically create a new evidence subject, the minimum post-transform test set for tool-using models, how evidence composes across chained transformations, whether runtime attestation can prove exact admitted bytes are executing, and when deterministic equivalence can replace behavioral testing.</p><p>The bounded conclusion is: <strong>when a transformation can change behavior relevant to safety or business admission, its output becomes a new evidence subject. Lineage proves ancestry; deployment authorization must bind the exact artifact that will run.</strong></p><p><strong>Evidence and source:</strong></p><ul><li><a href="https://arxiv.org/abs/2609.14060" target="_blank" rel="noreferrer">AgentQ and quantization-triggered function-action backdoor research</a>, 2026.</li></ul>',33))])}const b=a(d,[["render",l]]);export{f as __pageData,b as default};
